#!/usr/bin/env python3
"""
Round 124b (culprits), 2 October 2026. Needs round 123b.

Each fire record from Global Forest Watch says which country it is in and
links to its spot on OpenStreetMap.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

HEAD = "## Round 124b (2 October)"


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round124b: run from the culprits repository root")
    text = (root / "HANDOFF.md").read_text(encoding="utf-8")
    if "## Round 123b" not in text:
        sys.exit("round124b: round 123b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round124b: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", check=False)
            sys.exit("round124b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round124b: applied")
    h = root / "HANDOFF.md"
    text = h.read_text(encoding="utf-8")
    if HEAD not in text:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + NOTE + text[at:], encoding="utf-8")


NOTE = "## Round 124b (2 October)\n\nNeeds round 123b. Tiles patch round124b_tiles.py beside it. No app.js?v= bump.\n\n- GFW records that carry their own latitude and longitude (the VIIRS fires)\n  show the country they fall in, from the map's own outlines (countryNameAt,\n  COUNTRY_SHAPES), and a link to the spot on OpenStreetMap (recordWhere).\n  NASA names no fires.\n- tiles medical_culprits.py: the company is read from the settlements\n  table's own Company column (it took drug names such as Neurontin and\n  Zoladex as companies); rows under cells spanning several rows carry them down.\n\n"
DIFF = ""

if __name__ == "__main__":
    main()
